function renamePlayerFleets(){const names=['f1','f2','f3'].map(id=>String(document.getElementById('fleetName-'+id)?.value||'').trim());if(names.some(n=>!/^[a-z0-9]{3,15}$/i.test(n))||new Set(names.map(n=>n.toLowerCase())).size!==3)return notify('Use three distinct names of 3–15 letters or numbers.',true);state.fleetNames=Object.fromEntries(['f1','f2','f3'].map((id,i)=>[id,names[i]]));for(const m of state.missions)m.name=fleetLabel(m.fleet);update();notify('Fleet names saved.');}
function renderFleetExtensions(){const el=document.getElementById('fleetExtensions');if(!el)return;el.innerHTML='<section class="panel"><div class="ph"><div class="pt">PERSONALISED FLEET NAMES</div></div><div class="controls">'+['f1','f2','f3'].map(id=>'<label class="field" for="fleetName-'+id+'">'+id.toUpperCase()+'<input id="fleetName-'+id+'" minlength="3" maxlength="15" value="'+esc(fleetLabel(id).replace(/ /g,''))+'"></label>').join('')+'<button class="btn primary" data-rename-fleets>SAVE FLEET NAMES</button></div></section>'+shipAnalysisHTML();const select=document.getElementById('missionFleet');if(select)for(const option of select.options||[])option.textContent=fleetLabel(option.value);}
function shipAnalysisHTML(){const rows=['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'].map(cls=>{const damage={Norm:0,EMP:0,Steal:0};for(const [id,d] of Object.entries(SHIPS)){const n=shipTotal(id);if(d.target?.[0]===cls&&damage[d.type]!==undefined)damage[d.type]+=n*(d.guns||0)*(d.type==='EMP'?1:(d.damage||0));}return '<tr><td>'+cls+'</td><td>'+nfmt(damage.Norm)+'</td><td>'+nfmt(damage.EMP)+'</td><td>'+nfmt(damage.Steal)+'</td></tr>';});return '<section class="panel" style="margin-top:18px"><div class="ph"><div class="pt">SHIP ANALYSIS · PRIMARY TARGETS</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Target class</th><th>Normal damage</th><th>EMP shots</th><th>Steal damage</th></tr></thead><tbody>'+rows.join('')+'</tbody></table></div><p class="note" style="margin:12px">Includes ready and deployed ships. Potential first-target damage before enemy armour, resistance and initiative; use the battle calculator for combat outcomes.</p></section>';}
function shipSaleQuote(id,qty){const d=SHIPS[id];return Object.fromEntries(['metal','crystal','eonium'].map(k=>[k,Math.floor((d?.cost[k]||0)*qty*.5)]));}
function sellPlayerShips(){const id=document.getElementById('saleShip')?.value,qty=Number(document.getElementById('saleQuantity')?.value);if(!SHIPS[id]||!Number.isSafeInteger(qty)||qty<1||(state.fleets.base[id]||0)<qty)return notify('Choose a valid quantity of ships in the Base fleet.',true);const quote=shipSaleQuote(id,qty);if(!confirm('Sell '+qty+' '+SHIPS[id].name+' ships? They are unavailable for 12 ticks. Payout: '+constructionCostText(quote)+'.'))return;state.fleets.base[id]-=qty;state.shipSales=state.shipSales||[];state.shipSales.push({id:Math.random().toString(36).slice(2),ship:id,qty,quote,startedTick:state.tick,dueTick:state.tick+12,cancelled:false});addNews(qty+' '+SHIPS[id].name+' ships sent to the vendor. Payout in 12 ticks.','info');update();}
function cancelShipSale(id){const order=(state.shipSales||[]).find(o=>o.id===id);if(!order||order.cancelled)return;order.cancelled=true;order.dueTick=state.tick+12;addNews('Ship sale cancelled. Ships return to Base in 12 ticks.','info');update();}
function settleShipSales(){for(const o of [...(state.shipSales||[])]){if(o.dueTick>state.tick)continue;if(o.cancelled)state.fleets.base[o.ship]=(state.fleets.base[o.ship]||0)+o.qty;else for(const k of Object.keys(o.quote))state.resources[k]+=o.quote[k];state.shipSales=state.shipSales.filter(x=>x.id!==o.id);addNews(o.cancelled?'Vendor returned '+o.qty+' ships to Base.':'Vendor sale completed: '+constructionCostText(o.quote)+'.','good');}}
function renderShipSales(){const el=document.getElementById('shipSales');if(!el)return;el.innerHTML='<section class="panel"><div class="ph"><div class="pt">SELL SHIPS · VENDOR</div><span class="meta">12-TICK SETTLEMENT</span></div><div class="controls"><label class="field" for="saleShip">Base fleet ship<select id="saleShip">'+Object.entries(state.fleets.base).filter(([id,n])=>SHIPS[id]&&n>0).map(([id,n])=>'<option value="'+id+'">'+esc(SHIPS[id].name)+' · '+nfmt(n)+' available</option>').join('')+'</select></label><label class="field" for="saleQuantity">Quantity<input id="saleQuantity" type="number" min="1" value="1"></label><button class="btn" data-sell-ships>SELL SHIPS</button></div><p class="note" style="margin:12px">Practice vendor pays 50% of the catalog resource price. Ships continue to count toward value while with the vendor. Cancellation returns ships after a fresh 12-tick journey.</p>'+(state.shipSales||[]).map(o=>'<div class="order"><div><b>'+nfmt(o.qty)+' × '+esc(SHIPS[o.ship]?.name||o.ship)+'</b><small>'+(o.cancelled?'RETURNING':'SALE')+' · '+Math.max(0,o.dueTick-state.tick)+' ticks · '+constructionCostText(o.quote)+'</small><progress aria-label="Vendor order progress" max="12" value="'+Math.min(12,12-Math.max(0,o.dueTick-state.tick))+'"></progress></div>'+(!o.cancelled?'<button class="btn warn" data-cancel-sale="'+o.id+'">CANCEL SALE</button>':'')+'</div>').join('')+'</section>';}
document.addEventListener('click',e=>{if(e.target.closest('[data-rename-fleets]'))renamePlayerFleets();if(e.target.closest('[data-sell-ships]'))sellPlayerShips();const cancel=e.target.closest('[data-cancel-sale]');if(cancel)cancelShipSale(cancel.dataset.cancelSale);});
function allianceLaunchBayHTML(){const allowed=mayAlliance('launchBay'),fleet=state.fleets.f4||{},mission=state.missions.find(m=>m.fleet==='f4');return '<section class="panel launch-bay"><div class="ph"><div class="pt">ALLIANCE LAUNCH BAY · '+esc(state.alliance.name)+'</div><span class="meta">PERMANENT ALLIANCE CONTROL</span></div><div class="settings-body"><h3>Fourth fleet · Alliance Fleet</h3><p>This dedicated slot is always controlled through alliance defence permissions. Assign ships using Fleets → Transfer ships, or direct new production to Alliance Fleet.</p><div class="alliance-kpis"><div><small>READY SHIPS</small><b>'+nfmt(totalShips(fleet))+'</b></div><div><small>STATUS</small><b>'+(mission?esc(mission.phase.toUpperCase()):'DOCKED')+'</b></div><div><small>COMMAND ACCESS</small><b>'+(allowed?'AUTHORISED':'READ ONLY')+'</b></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Docked ship</th><th>Class</th><th>Amount</th></tr></thead><tbody>'+Object.entries(fleet).filter(([id,n])=>SHIPS[id]&&n>0).map(([id,n])=>'<tr><td>'+esc(SHIPS[id].name)+'</td><td>'+esc(SHIPS[id].class)+'</td><td>'+nfmt(n)+'</td></tr>').join('')+'</tbody></table></div>'+(mission?'<div class="order"><div><b>'+esc(mission.mission)+' · '+esc(mission.targetName)+'</b><small>'+esc(mission.phase)+' · ETA '+mission.eta+'</small><progress aria-label="Alliance Fleet journey progress" max="'+(mission.travelEta||5)+'" value="'+Math.max(0,(mission.travelEta||5)-mission.eta)+'"></progress></div><button class="btn warn" data-recall="'+mission.id+'" '+(allowed?'':'disabled')+'>RECALL ALLIANCE FLEET</button></div>':'<div class="controls"><label class="field" for="allianceBayTarget">Target<select id="allianceBayTarget">'+state.galaxy.filter(p=>!p.player&&!p.exiled).map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.coords)+'</option>').join('')+'</select></label><label class="field" for="allianceBayMission">Mission<select id="allianceBayMission"><option>Defence</option><option>Fake Defence</option><option>Attack</option></select></label><label class="field" for="allianceBayDelay">Delay (0–12 ticks)<input id="allianceBayDelay" type="number" min="0" max="12" value="0"></label><button class="btn primary" data-launch-alliance-fleet '+(!allowed||!totalShips(fleet)?'disabled':'')+'>LAUNCH ALLIANCE FLEET</button></div>')+'<p class="note">The dock above uses your practice round. The member readiness cards below can queue orders for other members’ permanent Alliance Fleet; each member’s game executes them when open. Access follows Alliance → Ranks → Control permanent Alliance Fleet.</p><a class="btn" href="/manual.html#fleet-operations">LAUNCH BAY MANUAL →</a></div></section>';}
function launchAllianceFleet(){if(!mayAlliance('launchBay'))return notify('Alliance defence permission is required.',true);const fleet=document.getElementById('missionFleet'),target=document.getElementById('missionTarget'),mission=document.getElementById('missionType'),delay=document.getElementById('missionDelay'),previous=[fleet.value,target.value,mission.value,delay.value];const option=document.createElement('option');option.value='f4';option.textContent='Alliance Fleet';fleet.append(option);fleet.value='f4';target.value=document.getElementById('allianceBayTarget').value;mission.value=document.getElementById('allianceBayMission').value;delay.value=document.getElementById('allianceBayDelay').value;launchMission(true);option.remove();[fleet.value,target.value,mission.value,delay.value]=previous;}
document.addEventListener('click',e=>{if(e.target.closest('[data-launch-alliance-fleet]'))launchAllianceFleet();});
let allianceReadinessReports=[],fleetSyncBusy=false,fleetSyncAt=0;
async function allianceFleetRequest(body,mine=false){const r=await fetch('/api/alliance-fleets'+(mine?'?mine=1':''),{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}),data=await r.json();if(!r.ok)throw Error(data.error||'Fleet service unavailable.');return data;}
async function syncAllianceFleetReadiness(force=false){if(typeof fetch!=='function'||fleetSyncBusy||(!force&&Date.now()-fleetSyncAt<30000))return;fleetSyncBusy=true;fleetSyncAt=Date.now();try{const idle={};for(const slot of ['base','f1','f2','f3','f4'])idle[slot]=state.missions.some(m=>m.fleet===slot)?{}:state.fleets[slot]||{};await allianceFleetRequest({action:'snapshot',tick:state.tick,fleets:idle,names:state.fleetNames||{},allianceEta:reportedAllianceShipEtas()});const pending=await allianceFleetRequest(null,true);for(const c of pending.commands||[]){state.appliedAllianceCommands=state.appliedAllianceCommands||{};let status=state.appliedAllianceCommands[c.id];if(!status){const fleet=document.getElementById('missionFleet'),target=document.getElementById('missionTarget'),type=document.getElementById('missionType'),delay=document.getElementById('missionDelay'),old=[fleet.value,target.value,type.value,delay.value],option=document.createElement('option');option.value='f4';option.textContent='Alliance Fleet';fleet.append(option);fleet.value='f4';target.value=c.targetId;type.value=c.mission;delay.value=c.delay;const before=state.missions.length;launchMission('central');option.remove();[fleet.value,target.value,type.value,delay.value]=old;status=state.missions.length>before?'Executed':'Rejected';state.appliedAllianceCommands[c.id]=status;save();}await allianceFleetRequest({action:'ack',id:c.id,status});}if((pending.commands||[]).length){const refreshed={};for(const slot of ['base','f1','f2','f3','f4'])refreshed[slot]=state.missions.some(m=>m.fleet===slot)?{}:state.fleets[slot]||{};await allianceFleetRequest({action:'snapshot',tick:state.tick,fleets:refreshed,names:state.fleetNames||{},allianceEta:reportedAllianceShipEtas()});}if(mayAlliance('fleetStatus')){const data=await allianceFleetRequest();allianceReadinessReports=data.alliance===state.alliance.name?data.fleets:[];if(['defence','launchbay'].includes(allianceTab))renderAlliance();}}catch(error){const el=document.getElementById('fleetReadinessStatus');if(el)el.textContent=error.message;}finally{fleetSyncBusy=false;}}
function allianceReadinessHTML(){if(!mayAlliance('fleetStatus'))return '';return '<section class="panel fleet-readiness-module"><div class="ph"><div class="pt">MEMBER FLEET READINESS</div><button class="btn" data-refresh-fleet-readiness>REFRESH</button></div><p id="fleetReadinessStatus" class="note">Reported idle fleets only. No report means unknown; reports older than five minutes are marked stale.</p><div class="fleet-readiness-grid">'+state.alliance.members.map(member=>{const report=allianceReadinessReports.find(r=>r.planetId===member.planetId||r.coords===member.coords),stale=report&&Date.now()-report.updatedAt>300000;return '<article class="fleet-member-box"><header><h3>'+esc(member.planet)+'</h3><span class="tag">'+esc(member.rank)+'</span></header><small>'+esc(member.coords)+' · '+(report?(stale?'STALE · ':'')+new Date(report.updatedAt).toLocaleTimeString():'NO FLEET REPORT')+'</small>'+(report?Object.entries(report.fleets).map(([slot,ships])=>'<section class="fleet-slot-box"><b>'+esc(report.names?.[slot]||({base:'Base fleet',f1:'Fleet 1',f2:'Fleet 2',f3:'Fleet 3',f4:'Alliance Fleet'})[slot])+'</b>'+(Object.keys(ships).length?allianceReadinessTable(ships,report):'<p>No reported idle ships</p>')+(slot==='f4'&&mayAlliance('launchBay')&&!stale&&Object.keys(ships).length?'<button class="btn" data-command-member-fleet="'+esc(report.planetId)+'">PREPARE ALLIANCE LAUNCH</button>':'')+'</section>').join(''):'<p>This member has not reported fleet readiness.</p>')+'</article>';}).join('')+'</div><div id="memberFleetCommand"></div></section>';}
document.addEventListener('click',e=>{if(e.target.closest('[data-refresh-fleet-readiness]'))syncAllianceFleetReadiness(true);const prepare=e.target.closest('[data-command-member-fleet]');if(prepare&&mayAlliance('launchBay')){document.getElementById('memberFleetCommand').innerHTML='<section class="panel"><div class="ph"><div class="pt">ALLIANCE COMMAND · FOURTH FLEET</div></div><div class="controls"><label class="field" for="memberFleetTarget">Target<select id="memberFleetTarget">'+state.galaxy.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.coords)+'</option>').join('')+'</select></label><label class="field" for="memberFleetMission">Mission<select id="memberFleetMission"><option>Defence</option><option>Fake Defence</option><option>Attack</option></select></label><label class="field" for="memberFleetDelay">Delay<input id="memberFleetDelay" type="number" min="0" max="12" value="0"></label><button class="btn primary" data-send-member-command="'+esc(prepare.dataset.commandMemberFleet)+'">SEND LAUNCH ORDER</button></div><p class="note">The member’s open practice game receives and validates this order on its next readiness sync. Offline games wait until reopened.</p></section>';}const send=e.target.closest('[data-send-member-command]');if(send&&mayAlliance('launchBay')){send.disabled=true;allianceFleetRequest({action:'launch',planetId:send.dataset.sendMemberCommand,targetId:document.getElementById('memberFleetTarget').value,mission:document.getElementById('memberFleetMission').value,delay:Number(document.getElementById('memberFleetDelay').value)}).then(()=>notify('Alliance launch order queued.')).catch(error=>notify(error.message,true)).finally(()=>send.disabled=false);}});
if(typeof fetch==='function')setInterval(()=>syncAllianceFleetReadiness(),30000);
function addFleetToCalc(fleetId){if(!state.fleets[fleetId])return;const ships=copy(state.fleets[fleetId]);for(const m of state.missions.filter(m=>m.fleet===fleetId))for(const [id,count] of Object.entries(m.ships))ships[id]=(ships[id]||0)+count;window.bcalc=window.bcalc||{a:{},d:{}};window.bcalc.a=ships;window.bcalcResult='Loaded '+esc(fleetLabel(fleetId))+' as attacker. Defender input is preserved.';allianceTab='bcalc';navigate('alliance');renderAlliance();notify(fleetLabel(fleetId)+' added to the battle calculator.');}
document.addEventListener('click',e=>{const button=e.target.closest('[data-fleet-to-calc]');if(button)addFleetToCalc(button.dataset.fleetToCalc);});
function networkMissionRows(list,intel){if(!list.length)return '<tr><td colspan="7">No reported fleet movements.</td></tr>';return list.map(m=>{const target=state.galaxy.find(p=>p.id===m.targetId),coords=target?.coords||m.coords||'Unknown',record=intel&&mayIntelField('assessment')?state.alliance.intelRecords?.[coords]:null,origin=m.origin||homeGalaxy();return '<tr><td><b>'+esc(m.name||'Reported hostile fleet')+'</b><small>'+esc(origin)+'</small></td><td>'+esc(m.targetName||m.planet||'Unknown')+'<small>'+esc(coords)+'</small></td><td>'+esc(m.mission||'Reported incoming')+'</td><td>'+esc(m.phase==='scheduled'?'Launch T'+m.launchTick:m.phase||'Reported')+'</td><td>'+Math.max(0,m.eta||0)+'</td><td>'+(m.ships?nfmt(totalShips(m.ships)):esc(m.attackerCount||'Unknown'))+'</td><td>'+(record?esc(record.status||'Unassessed'):'—')+'</td></tr>';}).join('');}
function renderNetworkHub(){const el=document.getElementById('networkHubContent');if(!el)return;const allowed=mayAlliance('intel'),intel=allowed&&!!state.userSettings.networkIntel,own=state.missions.filter(m=>m.phase!=='returning'),incoming=own.filter(m=>galaxyOf(state.galaxy.find(p=>p.id===m.targetId)?.coords||'')===homeGalaxy());if(intel)incoming.push(...state.alliance.calls.filter(c=>galaxyOf(c.coords||state.galaxy.find(p=>p.name===c.planet)?.coords||'')===homeGalaxy()).map(c=>({...c,name:'Alliance threat report',origin:'Reported / unknown',mission:'Hostile incoming',phase:'Reported',attackerCount:c.attackerCount})));const table=(title,list)=>'<section class="panel network-fleet-box"><div class="ph"><div class="pt">'+title+'</div><span class="meta">'+list.length+' REPORTED</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Fleet / origin</th><th>Target</th><th>Mission</th><th>Status</th><th>ETA</th><th>Ships</th><th>Intel</th></tr></thead><tbody>'+networkMissionRows(list,intel)+'</tbody></table></div></section>';el.innerHTML='<section class="panel"><div class="controls"><label><input id="networkIntelEnabled" type="checkbox" '+(intel?'checked':'')+' '+(allowed?'':'disabled')+'> Enable alliance intel</label><span class="meta">'+(intel?'PERMITTED ALLIANCE INTEL ENABLED':'PERSONAL FLEET MOVEMENTS')+'</span></div><p class="note" style="margin:12px">Shows reported movements in this practice round. Alliance threat reports appear when intel is enabled; unknown origins and ship counts remain unknown. Fleets travelling within this galaxy appear in both departure and arrival views.</p></section><div class="network-fleet-layout">'+table('INCOMING FLEETS',incoming)+table('OUTGOING FLEETS',own)+table('RETURNING FLEETS',state.missions.filter(m=>m.phase==='returning'))+'</div>';}
document.addEventListener('change',e=>{if(e.target.id==='networkIntelEnabled'){state.userSettings.networkIntel=mayAlliance('intel')&&e.target.checked;save();renderNetworkHub();if(state.userSettings.networkIntel&&typeof loadCentralIntelGalaxy==='function')loadCentralIntelGalaxy();}});
let movementSyncBusy=false,movementSyncAt=0;
function queueMovementReport(m,action,extra={}){if(m.targetId?.startsWith('structure-'))return;state.movementAuditQueue=state.movementAuditQueue||[];const report={action,missionId:m.id,targetId:m.targetId,mission:m.mission,generation:state.centralResetGeneration||0,tick:action==='launch'?m.launchTick:state.tick,ships:totalShips(m.ships),...extra};if(!state.movementAuditQueue.some(r=>r.missionId===m.id&&r.action===action))state.movementAuditQueue.push(report);save();}
async function syncMovementReports(){if(typeof fetch!=='function'||movementSyncBusy||Date.now()-movementSyncAt<10000||!state.movementAuditQueue?.length)return;movementSyncBusy=true;movementSyncAt=Date.now();try{for(const report of [...state.movementAuditQueue]){const response=await fetch('/api/fleet-movements',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(report)});if(response.ok||[400,403].includes(response.status)||report.generation!==(state.centralResetGeneration||0)){state.movementAuditQueue=state.movementAuditQueue.filter(r=>r!==report);save();}else break;}}catch{}finally{movementSyncBusy=false;}}
setInterval(syncMovementReports,15000);

function reportedAllianceShipEtas(){const target={coords:homeGalaxy()==='01:01'?'02:01:01':'01:01:01',alliance:state.alliance.name};return Object.fromEntries(Object.keys(SHIPS).map(id=>[id,fleetTravelTime({[id]:1},target,'Defence')]));}
function allianceReadinessTable(ships,report){return '<div class="table-wrap fleet-readiness-table-wrap"><table class="table fleet-readiness-table"><thead><tr><th scope="col">Ship</th><th scope="col">Amount</th><th scope="col">Class</th><th scope="col">Target 1</th><th scope="col">Target 2</th><th scope="col">Target 3</th><th scope="col" title="Reported defence ETA to an alliance member outside the home galaxy">Alliance ETA</th></tr></thead><tbody>'+Object.entries(ships).filter(([id,n])=>SHIPS[id]&&n>0).map(([id,count])=>{const d=SHIPS[id],targets=d.targetSlots||d.target||[];return '<tr data-ship-class="'+esc(d.class)+'"><td>'+esc(d.name)+'</td><td>'+nfmt(count)+'</td><td>'+esc(d.class)+'</td>'+[0,1,2].map(i=>'<td>'+esc(targets[i]||'')+'</td>').join('')+'<td>'+esc(galaxyOf(report.coords||'')===homeGalaxy()?5:(report.allianceEta?.[id]??''))+'</td></tr>';}).join('')+'</tbody></table></div><small class="fleet-eta-note">Alliance ETA: defence travel to your galaxy. Alliance members in your galaxy show 5 ticks; other galaxies use the reported travel estimate. Blank means no estimate was reported.</small>';}
